package com.learnagent.memory;
import jakarta.persistence.*;import java.time.*;import java.util.UUID;
@Entity@Table(name="memory_review_sessions")public class MemoryReviewSession{@Id private UUID id;@Column(name="review_date",nullable=false)private LocalDate reviewDate;@Enumerated(EnumType.STRING)@Column(nullable=false)private MemoryReviewSessionStatus status;@Column(name="planned_count",nullable=false)private int plannedCount;@Column(name="reviewed_count",nullable=false)private int reviewedCount;@Column(name="correct_count",nullable=false)private int correctCount;@Column(name="elapsed_seconds",nullable=false)private int elapsedSeconds;@Column(name="started_at",nullable=false)private Instant startedAt;@Column(name="completed_at")private Instant completedAt;protected MemoryReviewSession(){}public MemoryReviewSession(LocalDate date,int planned){id=UUID.randomUUID();reviewDate=date;plannedCount=planned;status=MemoryReviewSessionStatus.ACTIVE;startedAt=Instant.now();}public void record(MemoryRating rating,int seconds){reviewedCount++;elapsedSeconds+=Math.max(0,seconds);if(rating!=MemoryRating.AGAIN)correctCount++;if(reviewedCount>=plannedCount||elapsedSeconds>=900)complete();}public void complete(){status=MemoryReviewSessionStatus.COMPLETED;if(completedAt==null)completedAt=Instant.now();}public UUID getId(){return id;}public LocalDate getReviewDate(){return reviewDate;}public MemoryReviewSessionStatus getStatus(){return status;}public int getPlannedCount(){return plannedCount;}public int getReviewedCount(){return reviewedCount;}public int getCorrectCount(){return correctCount;}public int getElapsedSeconds(){return elapsedSeconds;}public Instant getStartedAt(){return startedAt;}public Instant getCompletedAt(){return completedAt;}}
